package lk.medical.model;
import java.time.LocalDate; import java.time.LocalTime;
public class Appointment { private String id,patientId,doctorId,status,reason,notes,feedback; private LocalDate date; private LocalTime time; public Appointment(){} public Appointment(String id,String patientId,String doctorId,LocalDate date,LocalTime time,String status,String reason,String notes,String feedback){this.id=id;this.patientId=patientId;this.doctorId=doctorId;this.date=date;this.time=time;this.status=status;this.reason=reason;this.notes=notes;this.feedback=feedback;} public boolean confirm(){if("CANCELLED".equals(status)||"COMPLETED".equals(status))return false;status="CONFIRMED";return true;} public String getId(){return id;} public void setId(String v){id=v;} public String getPatientId(){return patientId;} public void setPatientId(String v){patientId=v;} public String getDoctorId(){return doctorId;} public void setDoctorId(String v){doctorId=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public LocalTime getTime(){return time;} public void setTime(LocalTime v){time=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public String getFeedback(){return feedback;} public void setFeedback(String v){feedback=v;} }
